div.script:
// Spinner functionality
document.addEventListener('DOMContentLoaded', function() {
  // Get the spinner element
  const spinner = document.getElementById('spinner');

  // Make sure the spinner is visible during initial page load
  if (spinner) {
    spinner.classList.add('show');
  }

  // Hide spinner when everything is fully loaded
  window.addEventListener('load', function() {
    // Small delay to ensure everything is rendered
    setTimeout(function() {
      // Remove the "show" class to trigger the CSS transition
      if (spinner) {
        spinner.classList.remove('show');
      }

      // Dispatch a custom event when spinner is hidden
      setTimeout(function() {
        // Create and dispatch custom event after spinner transition completes
        const spinnerCompleteEvent = new CustomEvent('spinnerComplete');
        document.dispatchEvent(spinnerCompleteEvent);
      }, 500); // Match the spinner transition time

    }, 800); // Slightly longer delay to appreciate the overlay
  });
});
  document.querySelectorAll('.module').forEach(module => {
            module.addEventListener('mouseenter', () => {
                module.style.transform = 'translateX(5px)';
                module.style.borderLeftColor = '#4361ee';
                module.style.boxShadow = '0 3px 10px rgba(0, 0, 0, 0.05)';
            });

            module.addEventListener('mouseleave', () => {
                module.style.transform = '';
                module.style.borderLeftColor = 'transparent';
                module.style.boxShadow = '';
            });

            module.addEventListener('click', () => {
                const title = module.querySelector('.module-title').textContent;
                alert(`You're about to start the "${title}" module. Get ready to learn!`);
            });
        });

        // Button ripple effect
        document.getElementById('enrollBtn').addEventListener('click', function(e) {
            const button = this;

            // Create ripple element
            const ripple = document.createElement('span');
            ripple.classList.add('ripple');

            // Add ripple to button
            this.appendChild(ripple);

            // Get position of click relative to button
            const rect = button.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            // Set ripple position
            ripple.style.left = `${x}px`;
            ripple.style.top = `${y}px`;

            // Remove ripple after animation completes
            setTimeout(() => {
                ripple.remove();
            }, 600);

            // Show enrollment confirmation popup
            setTimeout(() => {
                alert('Thank you for enrolling in the Complete Web Development Bootcamp! Your journey to becoming a web developer starts now.');
            }, 300);
        });
